import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { User, UserTeam, Transaction } from '../types';

// The API_URL will be read from your .env file
const API_URL = process.env.REACT_APP_API_URL;

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<void>;
  logout: () => void;
  register: (userData: RegisterData) => Promise<void>;
  updateProfile: (data: Partial<User>) => Promise<void>;
  getUserTeams: () => UserTeam[];
  getTransactionHistory: () => Transaction[];
}

interface RegisterData {
  username: string;
  email: string;
  password: string;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

interface AuthProviderProps {
  children: ReactNode;
}

// Mock user data for fallback
const mockUser: User = {
  id: 'mock-user-1',
  username: 'demo_user',
  email: 'demo@play11.com',
  avatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150',
  balance: 5000,
  totalWinnings: 15000,
  totalContests: 45,
  winRate: 65.5,
  badges: [
    {
      id: 'badge-1',
      name: 'First Win',
      description: 'Won your first contest',
      icon: '🏆',
      earnedAt: '2024-01-15'
    }
  ],
  createdAt: '2024-01-01'
};

export const AuthProvider: React.FC<AuthProviderProps> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  // This function will run when the app loads to check if a user is already logged in
  useEffect(() => {
    const checkAuthStatus = async () => {
      const token = localStorage.getItem('play11_token');
      if (token) {
        try {
          // Try to verify token with the backend
          const response = await fetch(`${API_URL}/api/users/profile`, {
            headers: {
              'Authorization': `Bearer ${token}`
            }
          });

          if (response.ok) {
            const userData = await response.json();
            // Map backend user data to frontend User interface
            const mappedUser: User = {
              id: userData._id || userData.id,
              username: userData.username,
              email: userData.email,
              avatar: userData.avatar || undefined,
              balance: userData.balance || 0,
              totalWinnings: userData.totalWinnings || 0,
              totalContests: userData.totalContests || 0,
              winRate: userData.winRate || 0,
              badges: userData.badges || [],
              createdAt: userData.createdAt || new Date().toISOString()
            };
            setUser(mappedUser);
          } else {
            // Token is invalid, remove it
            localStorage.removeItem('play11_token');
            // For demo purposes, use mock user
            setUser(mockUser);
            localStorage.setItem('play11_token', 'demo-token');
          }
        } catch (error) {
          console.error('Auth check failed, using mock data:', error);
          localStorage.removeItem('play11_token');
          // For demo purposes, use mock user
          setUser(mockUser);
          localStorage.setItem('play11_token', 'demo-token');
        }
      } else {
        // No token, but for demo purposes, auto-login with mock user
        setUser(mockUser);
        localStorage.setItem('play11_token', 'demo-token');
      }
      setLoading(false);
    };

    checkAuthStatus();
  }, []);

  const login = async (email: string, password: string) => {
    setLoading(true);
    try {
      // Try backend authentication first
      const response = await fetch(`${API_URL}/api/users/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });

      if (response.ok) {
        const { token, user: userData } = await response.json();
        localStorage.setItem('play11_token', token);
        
        // Map backend user data to frontend User interface
        const mappedUser: User = {
          id: userData._id || userData.id,
          username: userData.username,
          email: userData.email,
          avatar: userData.avatar || undefined,
          balance: userData.balance || 0,
          totalWinnings: userData.totalWinnings || 0,
          totalContests: userData.totalContests || 0,
          winRate: userData.winRate || 0,
          badges: userData.badges || [],
          createdAt: userData.createdAt || new Date().toISOString()
        };
        setUser(mappedUser);
      } else {
        // Fallback to mock authentication for demo
        if (email === 'demo@play11.com' && password === 'demo123') {
          localStorage.setItem('play11_token', 'demo-token');
          setUser(mockUser);
        } else {
          throw new Error('Invalid credentials');
        }
      }
    } catch (error) {
      // For demo purposes, allow any email/password combination
      if (email && password.length >= 6) {
        localStorage.setItem('play11_token', 'demo-token');
        setUser({
          ...mockUser,
          email,
          username: email.split('@')[0]
        });
      } else {
        throw new Error('Invalid credentials');
      }
    } finally {
      setLoading(false);
    }
  };

  const logout = () => {
    localStorage.removeItem('play11_token');
    setUser(null);
  };

  const register = async (userData: RegisterData) => {
    setLoading(true);
    try {
      // Try backend registration first
      const response = await fetch(`${API_URL}/api/users/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(userData),
      });

      if (response.ok) {
        const { token, user: backendUser } = await response.json();
        localStorage.setItem('play11_token', token);
        
        // Map backend user data to frontend User interface
        const mappedUser: User = {
          id: backendUser._id || backendUser.id,
          username: backendUser.username,
          email: backendUser.email,
          avatar: backendUser.avatar || undefined,
          balance: backendUser.balance || 100,
          totalWinnings: 0,
          totalContests: 0,
          winRate: 0,
          badges: [],
          createdAt: backendUser.createdAt || new Date().toISOString()
        };
        setUser(mappedUser);
      } else {
        // Fallback to mock registration
        const newUser: User = {
          ...mockUser,
          id: 'user-new',
          username: userData.username,
          email: userData.email,
          balance: 100,
          totalWinnings: 0,
          totalContests: 0,
          winRate: 0,
          badges: []
        };
        
        localStorage.setItem('play11_token', 'new-user-token');
        setUser(newUser);
      }
    } catch (error) {
      // Fallback registration for demo
      const newUser: User = {
        ...mockUser,
        id: 'user-new',
        username: userData.username,
        email: userData.email,
        balance: 100,
        totalWinnings: 0,
        totalContests: 0,
        winRate: 0,
        badges: []
      };
      
      localStorage.setItem('play11_token', 'new-user-token');
      setUser(newUser);
    } finally {
      setLoading(false);
    }
  };

  // These functions can be implemented later with their respective backend endpoints
  const updateProfile = async (data: Partial<User>) => {
    console.log('updateProfile not implemented');
  };

  const getUserTeams = (): UserTeam[] => {
    return [];
  };

  const getTransactionHistory = (): Transaction[] => {
    return [];
  };

  const value = {
    user,
    loading,
    login,
    logout,
    register,
    updateProfile,
    getUserTeams,
    getTransactionHistory
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};
